//! Apply an anytime-valid bounded-risk e-process to the exact residual traces
//! generated by allostatic-sequential-scope-bench.
//!
//! Usage: allostatic-risk-eprocess-bench <sequential-raw.csv> <raw-out.csv> <summary-out.csv>
//! The input trace is reused verbatim so pointwise, CUSUM and e-process results
//! can be compared at identical episode/state/step coordinates.

use allostatic_control_bench::bounded_risk_eprocess::BoundedRiskEProcess;
use std::collections::BTreeMap;
use std::error::Error;
use std::fs;
use std::io::{Error as IoError, ErrorKind};

const HORIZON: usize = 8;
const CALIBRATED_RESIDUAL_SCALE: f64 = 0.05;
const RISK_BOUND: f64 = 0.15;
const GLOBAL_DELTA: f64 = 0.05;
const PARALLEL_MONITORS: usize = 5;
const BET: f64 = 0.5 / RISK_BOUND;

const INPUT_HEADER: &str = "operating_point,condition,episode_seed,step,residual_score,pointwise_threshold,pointwise_step_alarm,pointwise_first_alarm_step,cusum_statistic,cusum_threshold,cusum_latched_alarm,cusum_first_alarm_step,ground_truth_outside_predictor_envelope,all_episode_scores_below_pointwise_threshold";
const RAW_HEADER: &str = "operating_point,condition,episode_seed,step,residual_score,pointwise_threshold,pointwise_step_alarm,pointwise_first_alarm_step,cusum_statistic,cusum_threshold,cusum_latched_alarm,cusum_first_alarm_step,ground_truth_outside_predictor_envelope,all_episode_scores_below_pointwise_threshold,bounded_risk_loss,log_e_value,eprocess_latched_alarm,first_eprocess_alarm_step,log_e_alarm_threshold,risk_bound,bet";
const SUMMARY_HEADER: &str = "operating_point,condition,episodes,eprocess_alarms,eprocess_false_alarms,eprocess_missed_shifts,mean_detection_step,p95_detection_step,median_detection_step,episodes_all_scores_below_pointwise,eprocess_caught_below_pointwise,mean_final_log_e,max_final_log_e,log_alarm_threshold,risk_bound,bet,global_delta";

#[derive(Clone, Debug)]
struct InputRow {
    fields: Vec<String>,
    operating_point: String,
    condition: String,
    seed: u64,
    step: usize,
    residual_score: f64,
    pointwise_threshold: f64,
    all_scores_below_pointwise: bool,
}

impl InputRow {
    fn parse(line: &str) -> Result<Self, Box<dyn Error>> {
        let fields: Vec<String> = line.split(',').map(str::to_string).collect();
        if fields.len() != 14 {
            return Err(IoError::new(
                ErrorKind::InvalidData,
                format!("sequential input row has {} columns, expected 14", fields.len()),
            )
            .into());
        }
        let parse_number = |index: usize, label: &str| -> Result<f64, Box<dyn Error>> {
            fields[index].parse::<f64>().map_err(|_| {
                IoError::new(
                    ErrorKind::InvalidData,
                    format!("invalid {label} in sequential input"),
                )
                .into()
            })
        };
        let step = fields[3].parse::<usize>()?;
        let seed = fields[2].parse::<u64>()?;
        let all_scores_below_pointwise = match fields[13].as_str() {
            "true" => true,
            "false" => false,
            _ => {
                return Err(
                    IoError::new(ErrorKind::InvalidData, "invalid full-episode pointwise flag")
                        .into(),
                )
            }
        };
        Ok(Self {
            operating_point: fields[0].clone(),
            condition: fields[1].clone(),
            seed,
            step,
            residual_score: parse_number(4, "residual score")?,
            pointwise_threshold: parse_number(5, "pointwise threshold")?,
            all_scores_below_pointwise,
            fields,
        })
    }
}

#[derive(Clone, Debug, Default)]
struct CellSummary {
    episodes: usize,
    alarms: usize,
    false_alarms: usize,
    missed_shifts: usize,
    detection_steps: Vec<usize>,
    all_below_episodes: usize,
    caught_below_episodes: usize,
    final_log_values: Vec<f64>,
}

impl CellSummary {
    fn observe(
        &mut self,
        condition: &str,
        first_alarm_step: usize,
        all_scores_below_pointwise: bool,
        final_log_e_value: f64,
    ) {
        let detected = first_alarm_step < HORIZON;
        let shifted = condition != "nominal";
        self.episodes += 1;
        self.alarms += usize::from(detected);
        self.false_alarms += usize::from(!shifted && detected);
        self.missed_shifts += usize::from(shifted && !detected);
        if detected {
            self.detection_steps.push(first_alarm_step);
        }
        self.all_below_episodes += usize::from(all_scores_below_pointwise);
        self.caught_below_episodes +=
            usize::from(all_scores_below_pointwise && detected);
        self.final_log_values.push(final_log_e_value);
    }
}

fn validate_header(header: &str) -> Result<(), Box<dyn Error>> {
    if header != INPUT_HEADER {
        return Err(IoError::new(
            ErrorKind::InvalidData,
            "sequential input header does not match the pinned CUSUM benchmark schema",
        )
        .into());
    }
    Ok(())
}

fn percentile(values: &[usize], percentile: usize) -> Option<usize> {
    if values.is_empty() {
        return None;
    }
    let mut sorted = values.to_vec();
    sorted.sort_unstable();
    let rank = (sorted.len() * percentile).div_ceil(100).max(1);
    Some(sorted[rank - 1])
}

fn mean(values: &[f64]) -> Option<f64> {
    (!values.is_empty()).then(|| values.iter().sum::<f64>() / values.len() as f64)
}

fn optional_number<T: ToString>(value: Option<T>) -> String {
    value.map_or_else(|| "NA".to_string(), |number| number.to_string())
}

fn optional_float(value: Option<f64>) -> String {
    value.map_or_else(|| "NA".to_string(), |number| format!("{number:.9}"))
}

fn summary_row(
    output: &mut String,
    operating_point: &str,
    condition: &str,
    summary: &CellSummary,
    log_threshold: f64,
) {
    let fields = [
        operating_point.to_string(),
        condition.to_string(),
        summary.episodes.to_string(),
        summary.alarms.to_string(),
        summary.false_alarms.to_string(),
        summary.missed_shifts.to_string(),
        optional_float(mean(
            &summary
                .detection_steps
                .iter()
                .map(|step| *step as f64)
                .collect::<Vec<_>>(),
        )),
        optional_number(percentile(&summary.detection_steps, 95)),
        optional_number(percentile(&summary.detection_steps, 50)),
        summary.all_below_episodes.to_string(),
        summary.caught_below_episodes.to_string(),
        optional_float(mean(&summary.final_log_values)),
        optional_float(summary.final_log_values.iter().copied().reduce(f64::max)),
        format!("{log_threshold:.9}"),
        format!("{RISK_BOUND:.9}"),
        format!("{BET:.9}"),
        format!("{GLOBAL_DELTA:.9}"),
    ];
    output.push_str(&fields.join(","));
    output.push('\n');
}

fn process_episode(
    rows: &[InputRow],
    raw_output: &mut String,
    summaries: &mut BTreeMap<(String, String), CellSummary>,
    log_threshold: f64,
) -> Result<(), Box<dyn Error>> {
    if rows.len() != HORIZON {
        return Err(IoError::new(
            ErrorKind::InvalidData,
            format!("episode has {} rows, expected {HORIZON}", rows.len()),
        )
        .into());
    }
    let first = &rows[0];
    let mut monitor = BoundedRiskEProcess::new(
        RISK_BOUND,
        BET,
        GLOBAL_DELTA,
        PARALLEL_MONITORS,
    )
    .ok_or_else(|| IoError::new(ErrorKind::InvalidInput, "invalid e-process configuration"))?;
    let mut first_alarm_step = HORIZON;
    let mut episode_rows = Vec::with_capacity(HORIZON);
    let mut all_scores_below_pointwise = true;

    for (expected_step, row) in rows.iter().enumerate() {
        if row.operating_point != first.operating_point
            || row.condition != first.condition
            || row.seed != first.seed
            || row.step != expected_step
            || row.residual_score < 0.0
            || row.residual_score > 1.0
            || !row.residual_score.is_finite()
            || !row.pointwise_threshold.is_finite()
        {
            return Err(IoError::new(
                ErrorKind::InvalidData,
                "episode rows are not contiguous, unique and numerically valid",
            )
            .into());
        }

        let bounded_loss = (row.residual_score / CALIBRATED_RESIDUAL_SCALE).clamp(0.0, 1.0);
        let alarm = monitor.observe(bounded_loss).ok_or_else(|| {
            IoError::new(ErrorKind::InvalidData, "e-process rejected valid bounded loss")
        })?;
        if alarm && first_alarm_step == HORIZON {
            first_alarm_step = expected_step;
        }
        all_scores_below_pointwise &= row.residual_score <= row.pointwise_threshold;
        episode_rows.push((row, bounded_loss, monitor.log_e_value(), alarm));
    }

    if rows
        .iter()
        .any(|row| row.all_scores_below_pointwise != all_scores_below_pointwise)
    {
        return Err(IoError::new(
            ErrorKind::InvalidData,
            "input full-episode pointwise flag disagrees with reconstructed residual trace",
        )
        .into());
    }

    for (row, bounded_loss, log_e_value, alarm) in &episode_rows {
        let mut fields = row.fields.clone();
        fields.push(format!("{bounded_loss:.9}"));
        fields.push(format!("{log_e_value:.9}"));
        fields.push(if *alarm { "true" } else { "false" }.to_string());
        fields.push(first_alarm_step.to_string());
        fields.push(format!("{log_threshold:.9}"));
        fields.push(format!("{RISK_BOUND:.9}"));
        fields.push(format!("{BET:.9}"));
        raw_output.push_str(&fields.join(","));
        raw_output.push('\n');
    }

    let summary = summaries
        .entry((first.operating_point.clone(), first.condition.clone()))
        .or_default();
    summary.observe(
        &first.condition,
        first_alarm_step,
        all_scores_below_pointwise,
        monitor.log_e_value(),
    );
    Ok(())
}

fn main() -> Result<(), Box<dyn Error>> {
    let args: Vec<String> = std::env::args().collect();
    if args.len() != 4 {
        return Err(IoError::new(
            ErrorKind::InvalidInput,
            "usage: allostatic-risk-eprocess-bench <sequential-raw.csv> <raw-out.csv> <summary-out.csv>",
        )
        .into());
    }

    let input = fs::read_to_string(&args[1])?;
    let mut lines = input.lines();
    validate_header(
        lines
            .next()
            .ok_or_else(|| IoError::new(ErrorKind::InvalidData, "missing sequential header"))?,
    )?;
    let rows = lines
        .map(InputRow::parse)
        .collect::<Result<Vec<_>, _>>()?;
    if rows.len() != 48_000 {
        return Err(IoError::new(
            ErrorKind::InvalidData,
            format!("expected 48,000 sequential input rows, received {}", rows.len()),
        )
        .into());
    }

    let monitor = BoundedRiskEProcess::new(
        RISK_BOUND,
        BET,
        GLOBAL_DELTA,
        PARALLEL_MONITORS,
    )
    .ok_or_else(|| IoError::new(ErrorKind::InvalidInput, "invalid e-process config"))?;
    let log_threshold = monitor.alarm_threshold();

    let mut raw_output = format!("{RAW_HEADER}\n");
    let mut summaries = BTreeMap::new();
    for chunk in rows.chunks_exact(HORIZON) {
        process_episode(chunk, &mut raw_output, &mut summaries, log_threshold)?;
    }
    if summaries.len() != 20
        || summaries.values().any(|summary: &CellSummary| summary.episodes != 300)
    {
        return Err(IoError::new(
            ErrorKind::InvalidData,
            "e-process output did not cover all 20 state/condition cells",
        )
        .into());
    }

    let mut summary_output = format!("{SUMMARY_HEADER}\n");
    for ((operating_point, condition), summary) in summaries {
        summary_row(
            &mut summary_output,
            &operating_point,
            &condition,
            &summary,
            log_threshold,
        );
    }
    fs::write(&args[2], raw_output)?;
    fs::write(&args[3], summary_output)?;
    Ok(())
}
